// src/lib/mcp/tools/list-destinations.ts
var CATEGORIES = [
  "waterfall",
  "cave",
  "village",
  "viewpoint",
  "lake",
  "adventure",
  "wildlife",
  "river",
  "peak",
  "cultural"
];
var list_destinations_default = defineTool2({
  name: "list_destinations",
  title: "List Meghalaya destinations",
  description: "List Meghalaya (Northeast India) travel destinations XTSY covers \u2014 waterfalls, caves, living-root bridges, rivers, viewpoints and villages. Optionally filter by category or region.",
  inputSchema: {
    category: z2.enum(CATEGORIES).optional().describe("Filter by destination category."),
    region: z2.string().optional().describe("Filter by region, e.g. 'Cherrapunji & Sohra', 'Near Shillong'."),
    featuredOnly: z2.boolean().optional().describe("Return only featured destinations.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ category, region, featuredOnly }) => {
    let list = category ? getDestinationsByCategory(category) : region ? getDestinationsByRegion(region) : meghalayaDestinations;
    if (featuredOnly) list = list.filter((d) => d.featured);
    const results = list.map((d) => ({
      name: d.name,
      slug: d.slug,
      category: d.category,
      region: d.region,
      shortDescription: d.shortDescription,
      featured: !!d.featured,
      url: `https://xtsy.one/destinations/${d.slug}`
    }));
    const text = `${results.length} destination(s):
` + results.map((d) => `- ${d.name} (${d.category}, ${d.region}) \u2014 ${d.shortDescription}`).join("\n");
    return {
      content: [{ type: "text", text }],
      structuredContent: { destinations: results }
    };
  }
});

// src/lib/mcp/tools/get-destination.ts
import { defineTool as defineTool3 } from "npm:@lovable.dev/mcp-js@0.20.1";
import { z as z3 } from "npm:zod@^3.23.8";
var get_destination_default = defineTool3({
  name: "get_destination",
  title: "Get a Meghalaya destination",
  description: "Get full details for a single Meghalaya destination by its slug (e.g. 'dawki-umngot-river', 'nohkalikai-falls'): overview, best time to visit, how to reach, things to do, travel tips and nearby attractions.",
  inputSchema: {
    slug: z3.string().min(1).describe("Destination slug, e.g. 'living-root-bridge' or 'umiam-lake'.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ slug }) => {
    const d = getDestinationBySlug(slug.trim());
    if (!d) {
      return {
        content: [{ type: "text", text: `No destination found for slug "${slug}".` }],
        isError: true
      };
    }
    const detail = {
      name: d.name,
      slug: d.slug,
      category: d.category,
      region: d.region,
      description: d.description,
      bestTimeToVisit: d.bestTimeToVisit,
      howToReach: d.howToReach,
      thingsToDo: d.thingsToDo,
      travelTips: d.travelTips,
      nearbyAttractions: d.nearbyAttractions,
      url: `https://xtsy.one/destinations/${d.slug}`
    };
    const text = `${d.name} (${d.category}, ${d.region})

${d.description}

Best time: ${d.bestTimeToVisit}
How to reach: ${d.howToReach}

Things to do:
${d.thingsToDo.map((t) => `- ${t}`).join("\n")}

Travel tips:
${d.travelTips.map((t) => `- ${t}`).join("\n")}

Plan your stay in Shillong: https://xtsy.one/book`;
    return {
      content: [{ type: "text", text }],
      structuredContent: detail
    };
  }
});

