// src/lib/mcp/tools/list-tour-packages.ts
var REGIONS = ["Meghalaya", "Arunachal Pradesh", "Assam & Meghalaya"];
var list_tour_packages_default = defineTool4({
  name: "list_tour_packages",
  title: "List tour packages",
  description: "List XTSY signature tour packages across Meghalaya and Northeast India, with per-person prices in INR, duration and highlights. Optionally filter by region.",
  inputSchema: {
    region: z4.enum(REGIONS).optional().describe("Filter packages by region.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ region }) => {
    const list = SIGNATURE_PACKAGES.filter((p) => region ? p.region === region : true);
    const packages = list.map((p) => ({
      title: p.title,
      slug: p.slug,
      region: p.region,
      duration: p.duration,
      pricePerPersonInr: p.pricePerPerson,
      minGroup: p.minGroup ?? null,
      shortDescription: p.shortDescription,
      highlights: p.highlights,
      url: `https://xtsy.one/tours/${p.slug}`
    }));
    const text = `${packages.length} tour package(s):
` + packages.map(
      (p) => `- ${p.title} (${p.region}, ${p.duration}) \u2014 \u20B9${p.pricePerPersonInr.toLocaleString(
        "en-IN"
      )}/person`
    ).join("\n");
    return {
      content: [{ type: "text", text }],
      structuredContent: { packages }
    };
  }
});

// src/lib/mcp/tools/get-tour-package.ts
import { defineTool as defineTool5 } from "npm:@lovable.dev/mcp-js@0.20.1";
import { z as z5 } from "npm:zod@^3.23.8";
var get_tour_package_default = defineTool5({
  name: "get_tour_package",
  title: "Get a tour package",
  description: "Get full details and the day-by-day itinerary for a single XTSY tour package by its slug.",
  inputSchema: {
    slug: z5.string().min(1).describe("Tour package slug, e.g. 'meghalaya-explorer'.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ slug }) => {
    const p = getSignaturePackageBySlug(slug.trim());
    if (!p) {
      return {
        content: [{ type: "text", text: `No tour package found for slug "${slug}".` }],
        isError: true
      };
    }
    const itinerary = getPackageItinerary(p.slug) ?? [];
    const detail = {
      title: p.title,
      slug: p.slug,
      region: p.region,
      duration: p.duration,
      pricePerPersonInr: p.pricePerPerson,
      minGroup: p.minGroup ?? null,
      pickupDrop: p.pickupDrop,
      idealFor: p.idealFor,
      highlights: p.highlights,
      shortDescription: p.shortDescription,
      itinerary,
      url: `https://xtsy.one/tours/${p.slug}`
    };
    const itineraryText = itinerary.length ? "\n\nItinerary:\n" + itinerary.map(
      (d, i) => `${d.day ?? `Day ${i + 1}`}: ${d.title ?? ""}` + (d.route ? ` (${d.route})` : "") + (d.activities?.length ? ` \u2014 ${d.activities.join(", ")}` : "")
    ).join("\n") : "";
    const text = `${p.title} (${p.region}, ${p.duration})
\u20B9${p.pricePerPerson.toLocaleString(
      "en-IN"
    )}/person

${p.shortDescription}

Highlights:
${p.highlights.map((h) => `- ${h}`).join("\n")}` + itineraryText + `

Enquire: https://xtsy.one/tours/${p.slug}`;
    return {
      content: [{ type: "text", text }],
      structuredContent: detail
    };
  }
});

