// src/lib/mcp/tools/get-bistro-menu.ts
var get_bistro_menu_default = defineTool6({
  name: "get_bistro_menu",
  title: "Get TAB Bistro menu",
  description: "Get the TAB Bistro by XTSY menu (Shillong) \u2014 beverages, food, fusion dishes and more, with INR prices. Optionally filter to one menu section.",
  inputSchema: {
    section: z6.string().optional().describe("Optional section id or label to filter, e.g. 'beverages'.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ section }) => {
    const q = section?.trim().toLowerCase();
    const sections = q ? menuSections.filter(
      (s) => s.id.toLowerCase() === q || s.label.toLowerCase() === q
    ) : menuSections;
    if (q && sections.length === 0) {
      return {
        content: [{ type: "text", text: `No menu section matches "${section}".` }],
        isError: true
      };
    }
    const text = sections.map((s) => {
      const cats = s.categories.map(
        (c) => `  ${c.title}:
` + c.items.map((it) => `    - ${it.name} \u2014 ${it.price}`).join("\n")
      ).join("\n");
      return `${s.label}
${cats}`;
    }).join("\n\n");
    return {
      content: [{ type: "text", text: `TAB Bistro by XTSY menu:

${text}` }],
      structuredContent: { sections }
    };
  }
});

